import (
	"context"
	"fmt"
	"log"
	"os"

	trevol "github.com/trevol-si/trevol-go"
)

func main() {
	ctx := context.Background()
	c, err := trevol.NewClient(os.Getenv("TREVOL_API_KEY"))
	if err != nil {
		log.Fatal(err)
	}

	_, err = c.GeneralAPI.GetHealth(ctx).Execute()
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("ok")
}

