import si.trevol.Trevol;
import si.trevol.generado.model.BalanceTransactionList;

public class Ejemplo {
    public static void main(String[] args) throws Exception {
        Trevol trevol = Trevol.builder().apiKey(System.getenv("TREVOL_API_KEY")).build(); // tvl_test_… → trevol.environment() == TEST

        for (var item : trevol.paginate(
                cursor -> trevol.balance().listBalanceTransactions().limit(100).startingAfter(cursor).execute(),
                BalanceTransactionList::getData)) {
            System.out.println(item.getId());
        }
    }
}

