using Trevol.Generado.Model;

public static class Ejemplo
{
    public static async Task Main()
    {
        var trevol = new TrevolClient(Environment.GetEnvironmentVariable("TREVOL_API_KEY")); // tvl_test_… → trevol.Environment == TrevolEnvironment.Test

        var entrada = TrevolJson.Deserialize<WebhookEndpointUpdate>("""
            {
              "description": "Pausado mientras migramos el servidor",
              "status": "paused"
            }
            """);
        var resultado = await trevol.WebhookEndpoints.UpdateWebhookEndpointAsync(
            id: "we_3f0c1a2b3f0c1a2b3f0c1a2b3f0c1a2b",
            webhookEndpointUpdate: entrada
        );
        Console.WriteLine(TrevolJson.Serialize(resultado));
    }
}

updateWebhookEndpoint.go:
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"

	trevol "github.com/trevol-si/trevol-go"
	"github.com/trevol-si/trevol-go/generado"
)

func main() {
	ctx := context.Background()
	c, err := trevol.NewClient(os.Getenv("TREVOL_API_KEY"))
	if err != nil {
		log.Fatal(err)
	}

	var entrada generado.WebhookEndpointUpdate
	cuerpo := `{
  "description": "Pausado mientras migramos el servidor",
  "status": "paused"
}`
	if err := json.Unmarshal([]byte(cuerpo), &entrada); err != nil {
		log.Fatal(err)
	}

	resultado, _, err := c.WebhookEndpointsAPI.UpdateWebhookEndpoint(ctx, "we_3f0c1a2b3f0c1a2b3f0c1a2b3f0c1a2b").
		WebhookEndpointUpdate(entrada).
		Execute()
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(resultado)
}

